using System;
using System.Collections.Generic;

namespace Cnidaria.Arm;

internal enum ArmOperandEncoding : byte
{
    Register,
    Immediate,
    Pattern,
    Multiplier,
    FloatingImmediate,
    FloatingConstant,
    LogicalImmediate,
    MoveWideImmediate,
    AddImmediate,
    ShiftLeftImmediate,
    ShiftRightImmediate,
    ShiftedRegister,
    ExtendedRegister,
    A32Shifter,
    Memory,
    RegisterMemory,
    A32Memory,
    A32HalfMemory,
    A32VfpMemory,
    Relative,
    Address,
    PageAddress,
    RegisterList,
    SystemRegister,
    VectorElement,
    VectorList,
    PrefetchOperation,
}

internal enum ArmRegisterClass : byte
{
    General32,
    General64,
    Vector,
    ScalableVector,
    Predicate,
}

internal readonly record struct ArmOperandSpec
{
    public ArmOperandEncoding Encoding { get; init; }
    public ArmRegisterClass Class { get; init; }
    public int Size { get; init; }
    public uint Mask { get; init; }
    public uint ExtraMask { get; init; }
    public uint BaseMask { get; init; }
    public uint IndexMask { get; init; }
    public long Minimum { get; init; }
    public long Maximum { get; init; }
    public int Scale { get; init; }
    public int Bias { get; init; }
    public int RegisterLimit { get; init; }
    public int RegisterRotation { get; init; }
    public int Tie { get; init; }
    public ArmPredication Predication { get; init; }
    public ArmAddressingMode Mode { get; init; }
    public ArmExtendKind Extend { get; init; }
    public int Shift { get; init; }
    public int Count { get; init; }
    public int IndexSize { get; init; }
    public int BaseVectorSize { get; init; }
    public int VectorSize { get; init; }
    public bool IndexRotate { get; init; }
    public bool AllowSp { get; init; }
    public bool Invert { get; init; }
    public bool Optional { get; init; }
    public ArmOperand Default { get; init; }

    public ArmOperandSpec()
    {
        Scale = 1;
        RegisterLimit = 32;
        Tie = -1;
        Count = 1;
    }
}

internal sealed class ArmInstructionForm
{
    public ArmInstrKind Opcode { get; init; }
    public int XLen { get; init; }
    public uint Word { get; init; }
    public ArmIsaFlags Isa { get; init; }
    public ArmOperandSpec[] Operands { get; init; } = Array.Empty<ArmOperandSpec>();
    public int ConditionShift { get; init; } = -1;
    public bool ConditionalOnly { get; init; }
    public uint FlagMask { get; init; }
}

internal static class ArmInstructionForms
{
    private static readonly Dictionary<ArmInstrKind, List<ArmInstructionForm>> ByOpcode = new Dictionary<ArmInstrKind, List<ArmInstructionForm>>();

    static ArmInstructionForms()
    {
        Build();
    }

    public static IReadOnlyList<ArmInstructionForm> ForOpcode(ArmInstrKind opcode)
        => ByOpcode.TryGetValue(opcode, out List<ArmInstructionForm>? forms) ? forms : Array.Empty<ArmInstructionForm>();

    private static void Def(ArmInstrKind opcode, int xlen, uint word, params ArmOperandSpec[] operands)
        => Def(opcode, xlen, word, ArmIsaFlags.None, operands);

    private static void Def(ArmInstrKind opcode, int xlen, uint word, ArmIsaFlags isa, params ArmOperandSpec[] operands)
        => Add(new ArmInstructionForm { Opcode = opcode, XLen = xlen, Word = word, Isa = isa, Operands = operands });

    private static void Add(ArmInstructionForm form)
    {
        if (!ByOpcode.TryGetValue(form.Opcode, out List<ArmInstructionForm>? forms))
            ByOpcode.Add(form.Opcode, forms = new List<ArmInstructionForm>());
        forms.Add(form);
    }

    private static ArmOperandSpec Reg(ArmRegisterClass registerClass, int size, uint mask, bool allowSp = false)
        => new ArmOperandSpec { Encoding = ArmOperandEncoding.Register, Class = registerClass, Size = size, Mask = mask, AllowSp = allowSp };

    private static ArmOperandSpec G(int bit, int size, bool allowSp = false)
        => Reg(ArmRegisterClass.General64, size, 31u << bit, allowSp);

    private static ArmOperandSpec R(int bit)
        => Reg(ArmRegisterClass.General32, 4, 15u << bit, true);

    private static ArmOperandSpec V(int bit, int size)
        => Reg(ArmRegisterClass.Vector, size, 31u << bit);

    private static ArmOperandSpec Z(int bit, int size)
        => Reg(ArmRegisterClass.ScalableVector, size, 31u << bit);

    private static ArmOperandSpec P(int bit, int size = 0, ArmPredication predication = ArmPredication.None, int limit = 16)
        => Reg(ArmRegisterClass.Predicate, size, (uint)(limit - 1) << bit) with { Predication = predication, RegisterLimit = limit };

    private static ArmOperandSpec Tie(ArmOperandSpec operand, int index)
        => operand with { Mask = 0, Tie = index };

    private static ArmOperandSpec Imm(uint mask, long minimum, long maximum, int scale = 1, int bias = 0)
        => new ArmOperandSpec { Encoding = ArmOperandEncoding.Immediate, Mask = mask, Minimum = minimum, Maximum = maximum, Scale = scale, Bias = bias };

    private static ArmOperandSpec U(int bit, int bits)
        => Imm(((1u << bits) - 1) << bit, 0, (1L << bits) - 1);

    private static ArmOperandSpec S(int bit, int bits, int scale = 1)
        => Imm(((1u << bits) - 1) << bit, -(1L << (bits - 1)) * scale, ((1L << (bits - 1)) - 1) * scale, scale);

    private static ArmOperandSpec Optional(ArmOperandSpec spec, ArmOperand value)
        => spec with { Optional = true, Default = value };

    private static ArmOperandSpec Mem(uint mask, long minimum, long maximum, int scale = 1, ArmAddressingMode mode = ArmAddressingMode.Offset)
        => Imm(mask, minimum, maximum, scale) with { Encoding = ArmOperandEncoding.Memory, BaseMask = 31u << 5, Mode = mode };

    private static void A32(ArmInstrKind opcode, uint word, params ArmOperandSpec[] operands)
        => Add(new ArmInstructionForm { Opcode = opcode, XLen = 32, Word = word, Operands = operands, ConditionShift = 28 });

    private static void A32Flags(ArmInstrKind opcode, uint word, params ArmOperandSpec[] operands)
        => Add(new ArmInstructionForm { Opcode = opcode, XLen = 32, Word = word, Operands = operands, ConditionShift = 28, FlagMask = 1u << 20 });

    private static ArmOperandSpec V32(int field, int size)
        => Reg(ArmRegisterClass.Vector, size, field switch { 0 => 0x0040F000u, 1 => 0x000F0080u, _ => 0x0000002Fu }) with { RegisterRotation = field == 1 ? 1 : 0 };

    private static readonly (int Element, int Vector)[] Arrangements = { (1, 8), (1, 16), (2, 8), (2, 16), (4, 8), (4, 16), (8, 8), (8, 16) };

    private static ArmOperandSpec Vv(int bit, int element, int vector)
        => V(bit, element) with { VectorSize = vector };

    private static ArmOperandSpec VList(int bit, int element, int vector, int count)
        => V(bit, element) with { Encoding = ArmOperandEncoding.VectorList, VectorSize = vector, Count = count };

    private static ArmOperandSpec Element(int bit, int element, uint indexMask)
        => V(bit, element) with { Encoding = ArmOperandEncoding.VectorElement, ExtraMask = indexMask, Maximum = 16 / element - 1 };

    private static ArmOperandSpec ByElement(int element)
        => V(16, element) with
        {
            Encoding = ArmOperandEncoding.VectorElement,
            Mask = element == 2 ? 15u << 16 : 31u << 16,
            RegisterLimit = element == 2 ? 16 : 32,
            ExtraMask = element switch { 2 => 1u << 11 | 1u << 20 | 1u << 21, 4 => 1u << 11 | 1u << 21, _ => 1u << 11 },
            Maximum = 16 / element - 1,
            IndexRotate = true,
        };

    private static ArmOperandSpec Zero => Imm(0, 0, 0);

    private static ArmOperandSpec LeftShift(int element) => Imm(127u << 16, 0, element * 8 - 1, 1, element * 8);

    private static ArmOperandSpec RightShift(int element) => Imm(127u << 16, 1, element * 8, -1, element * 16);

    private static uint Q(int vector) => vector == 16 ? 1u << 30 : 0;

    private static uint Size(int element) => (uint)System.Numerics.BitOperations.Log2((uint)element) << 22;

    private static uint Sz(int element) => element == 8 ? 1u << 22 : 0;

    private static uint CopyMarker(int element) => 1u << (16 + System.Numerics.BitOperations.Log2((uint)element));

    private static uint CopyIndex(int element) => (0x1F0000u << (System.Numerics.BitOperations.Log2((uint)element) + 1)) & 0x1F0000u;

    private static bool Allows(string elements, int element)
        => elements.Contains(element switch { 1 => 'B', 2 => 'H', 4 => 'S', _ => 'D' });

    private static void Same(ArmInstrKind opcode, uint word, string elements, string scalar = "")
    {
        foreach ((int e, int v) in Arrangements)
        {
            if (Allows(elements, e) && (e != 8 || v == 16))
                Def(opcode, 64, word | Q(v) | Size(e), Vv(0, e, v), Vv(5, e, v), Vv(16, e, v));
        }
        foreach (char c in scalar)
        {
            int e = c switch { 'B' => 1, 'H' => 2, 'S' => 4, _ => 8 };
            Def(opcode, 64, word | 0x50000000u | Size(e), V(0, e), V(5, e), V(16, e));
        }
    }

    private static void FpSame(ArmInstrKind opcode, uint word, bool scalar = false)
    {
        foreach ((int e, int v) in new[] { (4, 8), (4, 16), (8, 16) })
            Def(opcode, 64, word | Q(v) | Sz(e), Vv(0, e, v), Vv(5, e, v), Vv(16, e, v));
        if (scalar)
        {
            foreach (int e in new[] { 4, 8 })
                Def(opcode, 64, word | 0x50000000u | Sz(e), V(0, e), V(5, e), V(16, e));
        }
    }

    private static void Misc(ArmInstrKind opcode, uint word, string elements, string scalar = "", bool zero = false)
    {
        foreach ((int e, int v) in Arrangements)
        {
            if (!Allows(elements, e) || e == 8 && v == 8)
                continue;
            if (zero)
                Def(opcode, 64, word | Q(v) | Size(e), Vv(0, e, v), Vv(5, e, v), Zero);
            else
                Def(opcode, 64, word | Q(v) | Size(e), Vv(0, e, v), Vv(5, e, v));
        }
        foreach (char c in scalar)
        {
            int e = c switch { 'B' => 1, 'H' => 2, 'S' => 4, _ => 8 };
            if (zero)
                Def(opcode, 64, word | 0x50000000u | Size(e), V(0, e), V(5, e), Zero);
            else
                Def(opcode, 64, word | 0x50000000u | Size(e), V(0, e), V(5, e));
        }
    }

    private static void FpMisc(ArmInstrKind opcode, uint word, bool scalar = false, bool zero = false, bool singleOnly = false)
    {
        foreach ((int e, int v) in new[] { (4, 8), (4, 16), (8, 16) })
        {
            if (singleOnly && e == 8)
                continue;
            if (zero)
                Def(opcode, 64, word | Q(v) | Sz(e), Vv(0, e, v), Vv(5, e, v), Zero);
            else
                Def(opcode, 64, word | Q(v) | Sz(e), Vv(0, e, v), Vv(5, e, v));
        }
        if (!scalar)
            return;
        foreach (int e in new[] { 4, 8 })
        {
            if (zero)
                Def(opcode, 64, word | 0x50000000u | Sz(e), V(0, e), V(5, e), Zero);
            else
                Def(opcode, 64, word | 0x50000000u | Sz(e), V(0, e), V(5, e));
        }
    }

    private static void Long(ArmInstrKind opcode, uint word, string elements)
    {
        foreach (int e in new[] { 1, 2, 4 })
        {
            if (!Allows(elements, e))
                continue;
            foreach (int v in new[] { 8, 16 })
                Def(opcode, 64, word | Q(v) | Size(e), Vv(0, e * 2, 16), Vv(5, e, v), Vv(16, e, v));
        }
    }

    private static void Wide(ArmInstrKind opcode, uint word)
    {
        foreach (int e in new[] { 1, 2, 4 })
        foreach (int v in new[] { 8, 16 })
            Def(opcode, 64, word | Q(v) | Size(e), Vv(0, e * 2, 16), Vv(5, e * 2, 16), Vv(16, e, v));
    }

    private static void Narrow(ArmInstrKind opcode, uint word)
    {
        foreach (int e in new[] { 1, 2, 4 })
        foreach (int v in new[] { 8, 16 })
            Def(opcode, 64, word | Q(v) | Size(e), Vv(0, e, v), Vv(5, e * 2, 16), Vv(16, e * 2, 16));
    }

    private static void NarrowMisc(ArmInstrKind opcode, uint word, bool scalar)
    {
        foreach (int e in new[] { 1, 2, 4 })
        {
            foreach (int v in new[] { 8, 16 })
                Def(opcode, 64, word | Q(v) | Size(e), Vv(0, e, v), Vv(5, e * 2, 16));
            if (scalar)
                Def(opcode, 64, word | 0x50000000u | Size(e), V(0, e), V(5, e * 2));
        }
    }

    private static void PairLong(ArmInstrKind opcode, uint word)
    {
        foreach (int e in new[] { 1, 2, 4 })
        foreach (int v in new[] { 8, 16 })
            Def(opcode, 64, word | Q(v) | Size(e), Vv(0, e * 2, v), Vv(5, e, v));
    }

    private static void Across(ArmInstrKind opcode, uint word, bool longResult)
    {
        foreach ((int e, int v) in new[] { (1, 8), (1, 16), (2, 8), (2, 16), (4, 16) })
            Def(opcode, 64, word | Q(v) | Size(e), V(0, longResult ? e * 2 : e), Vv(5, e, v));
    }

    private static void ShiftRight(ArmInstrKind opcode, uint word, bool scalar = true)
    {
        foreach ((int e, int v) in Arrangements)
        {
            if (e != 8 || v == 16)
                Def(opcode, 64, word | Q(v), Vv(0, e, v), Vv(5, e, v), RightShift(e));
        }
        if (scalar)
            Def(opcode, 64, word | 0x50000000u, V(0, 8), V(5, 8), RightShift(8));
    }

    private static void ShiftLeft(ArmInstrKind opcode, uint word, string scalar)
    {
        foreach ((int e, int v) in Arrangements)
        {
            if (e != 8 || v == 16)
                Def(opcode, 64, word | Q(v), Vv(0, e, v), Vv(5, e, v), LeftShift(e));
        }
        foreach (char c in scalar)
        {
            int e = c switch { 'B' => 1, 'H' => 2, 'S' => 4, _ => 8 };
            Def(opcode, 64, word | 0x50000000u, V(0, e), V(5, e), LeftShift(e));
        }
    }

    private static void ShiftNarrow(ArmInstrKind opcode, uint word, bool scalar)
    {
        foreach (int e in new[] { 1, 2, 4 })
        {
            foreach (int v in new[] { 8, 16 })
                Def(opcode, 64, word | Q(v), Vv(0, e, v), Vv(5, e * 2, 16), RightShift(e));
            if (scalar)
                Def(opcode, 64, word | 0x50000000u, V(0, e), V(5, e * 2), RightShift(e));
        }
    }

    private static void IntByElement(ArmInstrKind opcode, uint word, string scalar = "")
    {
        foreach (int e in new[] { 2, 4 })
        {
            foreach (int v in new[] { 8, 16 })
                Def(opcode, 64, word | Q(v) | Size(e), Vv(0, e, v), Vv(5, e, v), ByElement(e));
            if (Allows(scalar, e))
                Def(opcode, 64, word | 0x50000000u | Size(e), V(0, e), V(5, e), ByElement(e));
        }
    }

    private static void LongByElement(ArmInstrKind opcode, uint word, bool scalar = false)
    {
        foreach (int e in new[] { 2, 4 })
        {
            foreach (int v in new[] { 8, 16 })
                Def(opcode, 64, word | Q(v) | Size(e), Vv(0, e * 2, 16), Vv(5, e, v), ByElement(e));
            if (scalar)
                Def(opcode, 64, word | 0x50000000u | Size(e), V(0, e * 2), V(5, e), ByElement(e));
        }
    }

    private static void FpByElement(ArmInstrKind opcode, uint word)
    {
        foreach ((int e, int v) in new[] { (4, 8), (4, 16), (8, 16) })
            Def(opcode, 64, word | Q(v) | Sz(e), Vv(0, e, v), Vv(5, e, v), ByElement(e));
        foreach (int e in new[] { 4, 8 })
            Def(opcode, 64, word | 0x50000000u | Sz(e), V(0, e), V(5, e), ByElement(e));
    }

    private static void Build()
    {
        foreach ((ArmInstrKind opcode, uint a32, uint a64) in new[]
        {
            (ArmInstrKind.Nop, 0x0320F000u, 0xD503201Fu), (ArmInstrKind.Yield, 0x0320F001u, 0xD503203Fu),
            (ArmInstrKind.Wfe, 0x0320F002u, 0xD503205Fu), (ArmInstrKind.Wfi, 0x0320F003u, 0xD503207Fu),
            (ArmInstrKind.Sev, 0x0320F004u, 0xD503209Fu), (ArmInstrKind.Sevl, 0x0320F005u, 0xD50320BFu),
        })
        {
            A32(opcode, a32);
            Def(opcode, 64, a64);
        }
        Def(ArmInstrKind.Ret, 64, 0xD65F0000, Optional(G(5, 8), ArmOperand.RegisterOperand(ArmRegister.X30, 8)));
        Def(ArmInstrKind.Br, 64, 0xD61F0000, G(5, 8));
        Def(ArmInstrKind.Blr, 64, 0xD63F0000, G(5, 8));
        A32(ArmInstrKind.Ret, 0x012FFF10, Optional(R(0), ArmOperand.RegisterOperand(ArmRegister.Lr, 4)));
        A32(ArmInstrKind.Bx, 0x012FFF10, R(0));
        A32(ArmInstrKind.Blx, 0x012FFF30, R(0));
        foreach (ArmInstrKind opcode in new[] { ArmInstrKind.B, ArmInstrKind.Bl })
        {
            Def(opcode, 64, opcode == ArmInstrKind.B ? 0x14000000u : 0x94000000u, S(0, 26, 4) with { Encoding = ArmOperandEncoding.Relative });
            A32(opcode, opcode == ArmInstrKind.B ? 0x0A000000u : 0x0B000000u,
                S(0, 24, 4) with { Encoding = ArmOperandEncoding.Relative, Bias = -2 });
        }
        Add(new ArmInstructionForm { Opcode = ArmInstrKind.B, XLen = 64, Word = 0x54000000, ConditionShift = 0, ConditionalOnly = true,
            Operands = new[] { S(5, 19, 4) with { Encoding = ArmOperandEncoding.Relative } } });
        foreach (int size in new[] { 4, 8 })
        {
            uint sf = size == 8 ? 1u << 31 : 0;
            foreach ((ArmInstrKind opcode, uint word) in new[] { (ArmInstrKind.Cbz, 0x34000000u), (ArmInstrKind.Cbnz, 0x35000000u) })
                Def(opcode, 64, word | sf, G(0, size), S(5, 19, 4) with { Encoding = ArmOperandEncoding.Relative });
            foreach ((ArmInstrKind opcode, uint word) in new[] { (ArmInstrKind.Tbz, 0x36000000u), (ArmInstrKind.Tbnz, 0x37000000u) })
                Def(opcode, 64, word, G(0, size), Imm(0x80F80000, 0, size * 8 - 1), S(5, 14, 4) with { Encoding = ArmOperandEncoding.Relative });
        }
        Def(ArmInstrKind.Adr, 64, 0x10000000, G(0, 8), S(0, 21) with { Encoding = ArmOperandEncoding.Address });
        Def(ArmInstrKind.Adrp, 64, 0x90000000, G(0, 8), S(0, 21, 4096) with { Encoding = ArmOperandEncoding.PageAddress });

        foreach ((ArmInstrKind opcode, int operation, bool flags, bool unary, bool test) in new[]
        {
            (ArmInstrKind.And, 0, false, false, false), (ArmInstrKind.Ands, 0, true, false, false),
            (ArmInstrKind.Eor, 1, false, false, false), (ArmInstrKind.Sub, 2, false, false, false),
            (ArmInstrKind.Subs, 2, true, false, false), (ArmInstrKind.Rsb, 3, false, false, false),
            (ArmInstrKind.Add, 4, false, false, false), (ArmInstrKind.Adds, 4, true, false, false),
            (ArmInstrKind.Adc, 5, false, false, false), (ArmInstrKind.Adcs, 5, true, false, false),
            (ArmInstrKind.Sbc, 6, false, false, false), (ArmInstrKind.Sbcs, 6, true, false, false),
            (ArmInstrKind.Tst, 8, true, false, true), (ArmInstrKind.Teq, 9, true, false, true),
            (ArmInstrKind.Cmp, 10, true, false, true), (ArmInstrKind.Cmn, 11, true, false, true),
            (ArmInstrKind.Orr, 12, false, false, false), (ArmInstrKind.Mov, 13, false, true, false),
            (ArmInstrKind.Bic, 14, false, false, false), (ArmInstrKind.Bics, 14, true, false, false),
            (ArmInstrKind.Mvn, 15, false, true, false),
        })
        {
            ArmOperandSpec shifter = R(0) with { Encoding = ArmOperandEncoding.A32Shifter };
            ArmOperandSpec[] operands = unary ? new[] { R(12), shifter } : test ? new[] { R(16), shifter } : new[] { R(12), R(16), shifter };
            Add(new ArmInstructionForm { Opcode = opcode, XLen = 32, Word = (uint)operation << 21 | (flags ? 1u << 20 : 0),
                Operands = operands, ConditionShift = 28, FlagMask = 1u << 20 });
        }
        foreach ((ArmInstrKind opcode, uint word) in new[] { (ArmInstrKind.Movw, 0x03000000u), (ArmInstrKind.Movt, 0x03400000u) })
            A32(opcode, word, R(12), Imm(0x000F0FFF, 0, 65535));

        foreach (int size in new[] { 4, 8 })
        {
            uint sf = size == 8 ? 1u << 31 : 0;
            foreach ((ArmInstrKind opcode, bool sub, bool flags, bool test) in new[]
            {
                (ArmInstrKind.Add, false, false, false), (ArmInstrKind.Adds, false, true, false),
                (ArmInstrKind.Sub, true, false, false), (ArmInstrKind.Subs, true, true, false),
                (ArmInstrKind.Cmp, true, true, true), (ArmInstrKind.Cmn, false, true, true),
            })
            {
                uint bits = sf | (sub ? 1u << 30 : 0) | (flags ? 1u << 29 : 0) | (test ? 31u : 0);
                ArmOperandSpec immediate = U(10, 12) with { Encoding = ArmOperandEncoding.AddImmediate, Shift = 12, ExtraMask = 1u << 22 };
                ArmOperandSpec shifted = G(16, size) with { Encoding = ArmOperandEncoding.ShiftedRegister, Maximum = 2 };
                ArmOperandSpec extended = G(16, size) with { Encoding = ArmOperandEncoding.ExtendedRegister };
                Add(new ArmInstructionForm { Opcode = opcode, XLen = 64, Word = 0x11000000 | bits, FlagMask = 1u << 29,
                    Operands = test ? new[] { G(5, size, true), immediate } : new[] { G(0, size, !flags), G(5, size, true), immediate } });
                Add(new ArmInstructionForm { Opcode = opcode, XLen = 64, Word = 0x0B000000 | bits, FlagMask = 1u << 29,
                    Operands = test ? new[] { G(5, size), shifted } : new[] { G(0, size), G(5, size), shifted } });
                Add(new ArmInstructionForm { Opcode = opcode, XLen = 64, Word = 0x0B200000 | bits, FlagMask = 1u << 29,
                    Operands = test ? new[] { G(5, size, true), extended } : new[] { G(0, size, !flags), G(5, size, true), extended } });
            }
            foreach ((ArmInstrKind opcode, uint bits) in new[]
            {
                (ArmInstrKind.Adc, 0u), (ArmInstrKind.Adcs, 0x20000000u),
                (ArmInstrKind.Sbc, 0x40000000u), (ArmInstrKind.Sbcs, 0x60000000u),
            })
                Add(new ArmInstructionForm { Opcode = opcode, XLen = 64, Word = 0x1A000000 | sf | bits, FlagMask = 1u << 29,
                    Operands = new[] { G(0, size), G(5, size), G(16, size) } });
            foreach ((ArmInstrKind opcode, int operation, bool invert, bool test) in new[]
            {
                (ArmInstrKind.And, 0, false, false), (ArmInstrKind.Bic, 0, true, false),
                (ArmInstrKind.Orr, 1, false, false), (ArmInstrKind.Eor, 2, false, false),
                (ArmInstrKind.Ands, 3, false, false), (ArmInstrKind.Bics, 3, true, false),
                (ArmInstrKind.Tst, 3, false, true),
            })
            {
                uint bits = sf | ((uint)operation << 29) | (test ? 31u : 0);
                ArmOperandSpec immediate = new ArmOperandSpec { Encoding = ArmOperandEncoding.LogicalImmediate, Size = size, Mask = 0x007FFC00, Invert = invert };
                ArmOperandSpec shifted = G(16, size) with { Encoding = ArmOperandEncoding.ShiftedRegister, Maximum = 3 };
                Def(opcode, 64, 0x12000000 | bits, test ? new[] { G(5, size), immediate } : new[] { G(0, size, operation != 3), G(5, size), immediate });
                Def(opcode, 64, 0x0A000000 | bits | (invert ? 1u << 21 : 0), test ? new[] { G(5, size), shifted } : new[] { G(0, size), G(5, size), shifted });
            }
            Def(ArmInstrKind.Mov, 64, 0x52800000 | sf, G(0, size), new ArmOperandSpec { Encoding = ArmOperandEncoding.MoveWideImmediate, Size = size });
            Def(ArmInstrKind.Mov, 64, 0x12800000 | sf, G(0, size), new ArmOperandSpec { Encoding = ArmOperandEncoding.MoveWideImmediate, Size = size, Invert = true });
